from flask import Flask, request, redirect, jsonify
import html
import checks, ui, db

app = Flask(__name__)

# ---- SQLite: the table is created once; all students are saved in database.db ----
db.run("CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY, name TEXT, marks INTEGER)")
students = [{"name": r["name"], "marks": r["marks"]} for r in db.rows("SELECT name, marks FROM students ORDER BY id")]


def save():
    """Write the list to the database (simple way: clear the table, insert everyone again)."""
    db.many([("DELETE FROM students", ())] + [("INSERT INTO students (name, marks) VALUES (?, ?)", (s["name"], s["marks"])) for s in students])

@app.route("/")
def home():
    S = checks.load_all()
    form = '<form method="post" action="/add">' + ui.part(S[2]) + ui.part(S[3]) + ui.part(S[4]) + "</form>"

    if not students:
        lst = '<p style="color:#6b7480">No students yet. Add one above.</p>'
    elif S[5]["status"] != "done":
        lst = ui.box(S[5]) + '<p style="color:#6b7480">(%d student(s) saved, but not shown yet)</p>' % len(students)
    else:
        rows = []
        for i, s in enumerate(students):
            row = ui.part(S[5], {"name": html.escape(s["name"]), "marks": s["marks"]})
            extra = ""
            if S[7]["status"] == "done":
                extra += '<span class="badge">Grade %s</span>' % S[7]["f"](s["marks"])
            if S[9]["status"] == "done":
                extra += '<a class="del" href="/delete/%d" title="Delete">❌</a>' % i
            rows.append(row.replace("</li>", extra + "</li>") if "</li>" in row else row + extra)
        lst = "<ul>" + "".join(rows) + "</ul>"
        if S[7]["status"] != "done": lst += ui.box(S[7])
        if S[9]["status"] != "done": lst += ui.box(S[9])

    if S[6]["status"] == "done" and students:
        total = S[6]["f"](students)
        stats = '<div class="stats"><div class="stat">Total<b>%s</b></div><div class="stat">Average<b>%.1f</b></div></div>' % (total, total / len(students))
    elif S[6]["status"] == "done":
        stats = '<p style="color:#6b7480">Total and average appear after you add students.</p>'
    else:
        stats = ui.box(S[6])

    if S[8]["status"] == "done" and students:
        t = S[8]["f"](students)
        top = '<h2>🏆 Topper: %s (%s)</h2>' % (html.escape(t["name"]), t["marks"])
    elif S[8]["status"] == "done":
        top = ""
    else:
        top = ui.box(S[8])

    inner = ('<div class="card">' + ui.part(S[1]) + form + "</div>"
             + '<div class="card"><h2>Students</h2>' + lst + "</div>"
             + '<div class="card">' + stats + top + "</div>"
             + ui.part(S[10])
             + '<p style="text-align:center"><a href="/reset" style="color:#6b7480">Clear all students</a> · API: <a href="/api/students">/api/students</a></p>')
    return ui.page("Marks Analyzer", S, inner)


@app.route("/add", methods=["POST"])
def add():
    name = request.form.get("name", "").strip() or "Student %d" % (len(students) + 1)
    try:
        marks = int(request.form.get("marks", "0") or 0)
    except ValueError:
        marks = 0
    students.append({"name": name, "marks": marks})
    save()
    return redirect("/")


@app.route("/delete/<int:i>")
def delete(i):
    s = checks.load(9)
    if s["status"] == "done" and 0 <= i < len(students):
        s["f"](students, i)
        save()
    return redirect("/")


@app.route("/reset")
def reset():
    students.clear()
    save()
    return redirect("/")


# ==============================================================
#  API (CRUD) — ready-made. Call it with curl: commands/08_api_crud.txt
#  Create = POST · Read = GET · Update = PUT · Delete = DELETE
# ==============================================================
def body():
    return request.get_json(silent=True) or request.form


@app.get("/api/students")
def api_list():                                   # READ    SELECT * FROM students
    return jsonify([{"id": i, "name": s["name"], "marks": s["marks"]} for i, s in enumerate(students)])


@app.post("/api/students")
def api_create():                                 # CREATE  INSERT INTO students ...
    b = body()
    name = str(b.get("name", "")).strip()
    try:
        marks = int(b.get("marks", ""))
    except (TypeError, ValueError):
        return jsonify(error="marks must be a number"), 400
    if not name:
        return jsonify(error="name is required"), 400
    students.append({"name": name, "marks": marks})
    save()
    return jsonify(id=len(students) - 1, name=name, marks=marks), 201


@app.put("/api/students/<int:i>")
def api_update(i):                                # UPDATE  UPDATE students SET marks = ...
    if not 0 <= i < len(students):
        return jsonify(error="student not found"), 404
    try:
        students[i]["marks"] = int(body().get("marks", ""))
    except (TypeError, ValueError):
        return jsonify(error="marks must be a number"), 400
    save()
    return jsonify(id=i, **students[i])


@app.delete("/api/students/<int:i>")
def api_delete(i):                                # DELETE  DELETE FROM students WHERE id = ...
    if not 0 <= i < len(students):
        return jsonify(error="student not found"), 404
    gone = students.pop(i)
    save()
    return jsonify(deleted=gone["name"])


if __name__ == "__main__":
    print("\n  👉 Open http://localhost:5000 in your browser.  (Stop: Ctrl + C)\n")
    app.run(port=5000)
